function createAnalysisModule(services, _getModules) {
  const jobs = new AnalysisJobs(services);
  const done = new Map;
  const outfitImages = createOutfitImageController(services);
  const analysis = {
    start(params) {
      if (!params || typeof params.characterId !== "string" || !params.characterId.trim())
        fail2("bad-request", "characterId is required.");
      if (!SUPPORTED_ANALYSIS_KINDS.has(params.kind)) {
        fail2("unsupported", params.kind === "unique-tag-search" ? "Danbooru unique tag search is not available in this port." : `Analysis kind "${params.kind}" is not available yet.`, {
          detailCode: "ANALYSIS_KIND_UNSUPPORTED"
        });
      }
      const started = jobs.start(params.kind, params.characterId, (ctx) => runAnalysis(ctx, params));
      done.set(started.jobId, started.done.finally(() => done.delete(started.jobId)));
      return { jobId: started.jobId };
    },
    cancel(filter = {}) {
      return jobs.cancel(filter);
    },
    listActive() {
      return jobs.list();
    },
    async wait(jobId) {
      await done.get(jobId);
    },
    outfitImages,
    dispose() {
      jobs.dispose();
      outfitImages.dispose();
    }
  };
  return { analysis };
}
