// src/backend/analysis/assets.ts
var AM_FILTER = {
  all: "all",
  candidate: "candidate",
  chat: "chat-generated",
  outfit: "outfit-generated",
  original: "original"
};
async function listAssets(services, params) {
  const { characterId } = params;
  const [parts, images] = await Promise.all([loadAmConfigParts(services, characterId), services.sources.listCharacterImages(characterId, { includeGenerated: true }).catch(() => [])]);
  const rawSource = await services.sources.buildSource(characterId, parts.document);
  const source = amFn("y_")(rawSource, parts.document.customCharacters, "all") ?? rawSource;
  const store = new AmConfigStore(services, characterId, parts, "assets");
  const index = createAmPriorityAssets(store, (id) => id === source.id ? source : null);
  const promptKey = params.promptKey ?? "";
  const memberKey = params.memberKey ?? memberKeyOf(source, promptKey) ?? source.members[0]?.key ?? characterId;
  const descriptor = { sourceId: characterId, memberKey, promptKey, metadataOnly: params.metadataOnly === true };
  const entries = params.filter === "generated" ? [...pageAll(index, { ...descriptor, filter: "chat-generated" }), ...pageAll(index, { ...descriptor, filter: "outfit-generated" })] : pageAll(index, { ...descriptor, filter: AM_FILTER[params.filter] ?? "all" });
  const candidates = promptKey ? new Set(pageAll(index, { ...descriptor, filter: "candidate" }).map((e) => e.assetKey)) : new Set;
  const selection = promptKey ? new Set(AM.Pi(parts.document.characterPrompt.assetSelections[promptKey]?.selectedAssets ?? []).map((a) => AM.Gt(a))) : new Set;
  const byKey = new Map;
  for (const image of images) {
    byKey.set(image.imageId, image);
    if (image.asset?.key)
      byKey.set(image.asset.key, image);
  }
  const offset = Math.max(0, Number.parseInt(params.cursor ?? "0", 10) || 0);
  const limit = Math.max(1, Math.min(500, Math.floor(params.limit ?? 60)));
  const items = entries.slice(offset, offset + limit).map((entry) => {
    const image = byKey.get(entry.asset.key);
    return {
      asset: normalizeAssetRef(entry.asset),
      kind: entry.generatedKind,
      url: image?.url ?? "",
      thumbnailUrl: image?.thumbnailUrl || image?.url || "",
      ...image?.width ? { width: image.width } : {},
      ...image?.height ? { height: image.height } : {},
      ...entry.metadataState === "unknown" ? {} : { hasMetadata: entry.hasMetadata },
      selected: selection.has(entry.assetKey),
      candidate: candidates.has(entry.assetKey)
    };
  });
  return { items, nextCursor: offset + limit < entries.length ? String(offset + limit) : null, total: entries.length };
}
function pageAll(index, descriptor) {
  const count = index.getViewSnapshot(descriptor).count;
  return count ? index.getPage(descriptor, 0, count) : [];
}
function memberKeyOf(source, promptKey) {
  if (!promptKey)
    return null;
  for (const member of source.members)
    for (const lore of member.lorebooks)
      if (amFn("Hs")(member, lore) === promptKey)
        return member.key;
  return null;
}
function selectionTarget(characterId, promptKey) {
  return { kind: "asset-selection", sourceId: characterId, memberKey: "", lorebookId: "", promptKey, formId: "form_default", personaKey: "", outfitId: "" };
}
async function setSelection(services, characterId, promptKey, assets) {
  if (!promptKey)
    fail2("bad-request", "promptKey is required.");
  await mutateAmConfig(services, characterId, (c) => AM.ib(c, selectionTarget(characterId, promptKey), assets.map((a) => AM.sn(a))), { reason: "asset-selection" });
}
async function clearSelections(services, characterId, promptKeys) {
  await mutateAmConfig(services, characterId, (c) => {
    const keys = promptKeys?.length ? promptKeys : Object.keys(c.characterPrompt.assetSelections ?? {});
    return keys.reduce((acc, pk) => {
      const current = AM.jf(acc, selectionTarget(characterId, pk));
      return current.assets.length || current.assetNames.length ? AM.ib(acc, selectionTarget(characterId, pk), []) : acc;
    }, c);
  }, { reason: "asset-selection" });
}
async function setReference(services, target, asset) {
  const list = asset ? [AM.sn(asset)] : [];
  if (target.kind === "persona") {
    const characterId = target.characterId || (await services.sources.getActiveChat())?.characterId;
    if (!characterId)
      fail2("bad-request", "Open a chat (or pass characterId) to set a persona reference: persona references are stored per character.");
    const amTarget = target.outfitId ? { kind: "persona-outfit-reference", sourceId: characterId, personaKey: target.personaId, formId: target.formId ?? "form_default", outfitId: target.outfitId } : { kind: "persona-reference", sourceId: characterId, personaKey: target.personaId, formId: target.formId ?? "" };
    await mutateAmConfig(services, characterId, (c) => AM.ib(c, amTarget, list), { reason: "persona-reference" });
    return;
  }
  const characterId = target.characterId;
  const amTarget = target.kind === "artist-extraction" ? { kind: "artist-reference", sourceId: characterId, memberKey: "", promptKey: "", formId: "", outfitId: "" } : target.kind === "character-form" ? { kind: "character-reference", sourceId: characterId, promptKey: target.promptKey, formId: target.formId, outfitId: "" } : { kind: "outfit-reference", sourceId: characterId, promptKey: target.promptKey, formId: target.formId, outfitId: target.outfitId };
  await mutateAmConfig(services, characterId, (c) => AM.ib(c, amTarget, list), { reason: "reference" });
}
async function inspectMetadata(services, characterId, asset) {
  const session = await openAnalysisSession(services, characterId, { reason: "metadata" });
  try {
    const result = await session.metadata.inspect(AM.sn(asset));
    return { hasMetadata: result.hasMetadata === true, summary: result.summary ?? null, ...result.raw ? { raw: result.raw } : {} };
  } finally {
    session.dispose();
  }
}
async function clearMetadataRecords(services, characterId, recordKeys) {
  await services.storage.updateJson(metadataCachePath(characterId), {}, (current) => {
    if (!recordKeys?.length)
      return {};
    const next = { ...current ?? {} };
    for (const key of recordKeys)
      delete next[key];
    return next;
  });
}
var EXT_BY_MIME = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/avif": "avif", "image/gif": "gif" };
async function uploadAsset(services, params) {
  const data = base64ToBytes(params.dataBase64.replace(/^data:[^,]*,/u, ""));
  if (!data.length)
    fail2("bad-request", "The uploaded image is empty.");
  const extension = (params.fileName.split(".").pop() || EXT_BY_MIME[params.mimeType] || "png").toLowerCase();
  const name = params.fileName || `upload.${extension}`;
  const target = params.characterId ? { characterTarget: { chaId: params.characterId } } : {};
  try {
    const image = await services.host.images.upload({ data, filename: name, mime_type: params.mimeType, ...params.characterId ? { owner_character_id: params.characterId } : {} }, services.userId);
    return { asset: { name, key: image.id, extension, sourceType: "upload", moduleId: "", moduleName: "", ...target } };
  } catch (error) {
    services.log.append("warn", "assets", `Image upload through the host failed, storing the upload in extension storage: ${error instanceof Error ? error.message : String(error)}`);
  }
  const path = STORAGE_PATHS.upload(randomUuid(), extension);
  await services.storage.writeBinary(path, data);
  return { asset: { name, key: `${STORAGE_ASSET_PREFIX}${path}`, extension, sourceType: "upload", moduleId: "", moduleName: "", ...target } };
}
async function saveCrop(services, params) {
  const data = base64ToBytes(params.dataBase64.replace(/^data:[^,]*,/u, ""));
  if (!data.length)
    fail2("bad-request", "The crop image is empty.");
  const cropName = `${CROP_ASSET_NAME_PREFIX}${randomUuid()}`;
  const path = STORAGE_PATHS.characterReferenceCrop(params.characterId, cropName);
  await services.storage.writeBinary(path, data);
  const cropReference = {
    version: 1,
    assetName: `${cropName}.png`,
    assetKey: `${STORAGE_ASSET_PREFIX}${path}`,
    extension: "png",
    cropRect: params.cropRect,
    sourceSize: params.sourceSize
  };
  return { asset: { ...normalizeAssetRef(params.asset), cropReference } };
}
async function assetUrl(services, asset) {
  if (asset.key?.startsWith(STORAGE_ASSET_PREFIX)) {
    const bytes = await readAssetBytes(services, asset);
    return { url: `data:${bytes.mimeType};base64,${bytesToBase64(bytes.data)}` };
  }
  try {
    const image = await services.host.images.get(asset.key, services.userId);
    if (image?.url)
      return { url: image.url };
  } catch {}
  const chaId = asset.characterTarget?.chaId;
  if (chaId) {
    const images = await services.sources.listCharacterImages(chaId, { includeGenerated: true }).catch(() => []);
    const hit = images.find((i) => i.imageId === asset.key || i.asset?.key === asset.key);
    if (hit)
      return { url: hit.url };
  }
  fail2("not-found", `Image not found: ${asset.name || asset.key}`, { messageKo: `이미지를 읽지 못했습니다: ${asset.name || asset.key}` });
}

